             encodeURIComponent(c.u) + '&PassWord=' + encodeURIComponent(c.p) + '&CookieDate=1';
  var opt = '{"method":"POST","body":' + JSON.stringify(body) +
            ',"headers":{"User-Agent":' + JSON.stringify(EH_UA) +
            ',"Content-Type":"application/x-www-form-urlencoded"' +
            ',"Referer":"https://forums.e-hentai.org/index.php?act=Login&CODE=00"}}';
  var r, b = '';
  try {
