    b = String(r.body());
  } catch (e) { return { ok: false, reason: 'POST异常 ' + String(e).slice(0, 50) }; }
  if (/Just a moment|cf-mitigated|challenge|Checking your browser/i.test(b)) {
    return { ok: false, reason: 'Cloudflare 挑战页（需内置浏览器过盾）' };
  }
  if (/You are now logged in as|Logged in as|logout|Log Out/i.test(b)) {
    // 从响应头 Set-Cookie 或 CookieStore 取
    var raw = '';
    try { raw = String(r.headers()); } catch (e) {}
