// ==================== 261109 v3 增量：分辨率档位 / 线路测速 / 登录态检查 ====================
// 兼容要点（源码级实锤，261109 用户纠正后复核）：
//  ★★ E 版默认分支是 main（不是 master！）。main 的 RowUi.kt 明确支持
//    select/toggle/viewName/chars/default，SourceLoginDialog.kt 与官方版同尺寸(34267B)；
//    实例「🍥哔咔漫画」loginUi 里就有 {"type":"select","chars":[...],"default":...,"action":...}。
//    ⇒ 分辨率选择只用 select 下拉（双版本都可用）。
//  ★ select 选中值写进 loginInfo[name]，handleButtonClick 的 result=getLoginData()
//    = viewModel.loginInfo.toMutableMap() ⇒ action 里读 result['ehResSelect'] 即当前档位。
//    （哔咔实例读 infoMap[...] 亦可，二者都绑；本源统一用 result 通道，与 EH_input 一致。）
//  ★ 面板 action 环境 java = SourceLoginJsExtensions（ajax/connect/toast/startBrowserAwait 可用），
//    且 source.put/get 可落库（261107 已实锤，沿用现有 EH_set/EH_gv）。
//  ★ POST /uconfig.php 是写账号设置：必须用户主动点「同步站点档位」才发，绝不静默改。
//  ★ 裸 Cookie 覆盖 uconfig/xres 无效（261109 三组对照实锤）⇒ 服务端分辨率只能靠 POST。
//  ★ 站点真实表单：xr=0自动 / 1=780x / 3=1280x（4/5 需 Hath 已 disabled）；ts=0/1/2。

// ---- 分辨率档位表 ----
// hd   = ruleContent 阶段服务端内联高清张数（Rhino java.ajax，两版本都可用；60 封顶防站方限频）
// win  = WebView 视口懒加载并发窗口
// gap  = 每次 /s/ 请求间隔 ms（越小越快但越易触发站方短时限频）
// margin = IntersectionObserver 预取视口外边距
// orig = 是否在每格附「原图」链接
// xr/ts = 同步到站点 uconfig.php 的真实表单值
// ★ HD_MAX 克制在 0/6/15/25：站方对短时密集 /s/ 请求敏感（限频约 24h），
//   不因「超清档」把并发拉到 60 张；首屏之外的图一律交给 WebView 视口懒加载。
var EH_RES = [
  { k: '0', n: '省流·缩略图≈250px', hd: 0,  gap: 1000, margin: '0px',    xr: '1', ts: '0' },
  { k: '1', n: '自动·均衡≈780x',     hd: 6,  gap: 700,  margin: '600px',  xr: '0', ts: '0' },
  { k: '2', n: '高清·1280x(WiFi)',   hd: 15, gap: 450,  margin: '1200px', xr: '3', ts: '2' },
  { k: '3', n: '超清·全量·大屏',     hd: 25, gap: 350,  margin: '1800px', xr: '3', ts: '2' }
];
function EH_resCfg() {
  // 主存档 ehRes（由 select 的 EH_setRes 写入）；
  // 兼容：若面板 select 已选但 action 未触发，可从 result/infoMap 的标签反查档位。
  // ★261114 v5.3b：整个函数体包 try/catch —— 本函数在 viewName 求值环境里被
  //   EH_resStatus/EH_status 调用，任何一步异常都会让整个求值串变空 → 按钮显示 "null"。
  try {
    var k = EH_gv('ehRes', '1');
    var label = '';
    try { if (typeof result !== 'undefined' && result != null) {
            if (typeof result.get === 'function') { try { label = String(result.get('ehResSelect') || ''); } catch (e00) {} }
            if (!label) { try { label = String(result['ehResSelect'] || ''); } catch (e01) {} }
          } } catch (e0) {}
    if (!label) { try { if (typeof infoMap !== 'undefined' && infoMap) label = String(infoMap['ehResSelect'] || ''); } catch (e1) {} }
    if (label) {
      for (var i = 0; i < EH_RES.length; i++) {
        if (label.indexOf(EH_RES[i].n) >= 0) { k = EH_RES[i].k; break; }
      }
    }
    for (var j = 0; j < EH_RES.length; j++) if (EH_RES[j].k === k) return EH_RES[j];
    return EH_RES[1];
  } catch (eBig) { return EH_RES[1]; }
}
// select 的默认档位（供状态/说明用；default 字段本身是纯字符串，不走 JS 求值）
function EH_resDefault() {
  return EH_resCfg().n;
}
// ① 分辨率选择：select 下拉的 action（用户切换档位时由 SourceLoginDialog 自动回调）
//    ★ 选中值经 loginInfo → result 传来；同时兼容 infoMap 与 source.get 三通道。
function EH_setRes() {
  EH_toast('🖼 正在应用分辨率档位…');
  var label = '';
  try { label = String(result['ehResSelect'] || ''); } catch (e0) { label = ''; }
  if (!label) { try { label = String(infoMap['ehResSelect'] || ''); } catch (e1) { label = ''; } }
  if (!label) { try { label = String(result.get ? result.get('ehResSelect') : '') || ''; } catch (e2) { label = ''; } }
  var hit = null;
  for (var i = 0; i < EH_RES.length; i++) if (label.indexOf(EH_RES[i].n) >= 0) hit = EH_RES[i];
  if (!hit) {
    EH_toast('⚠ 未识别档位「' + label + '」，保持当前设置；请重新打开面板再选一次');
    return;
  }
  EH_set('ehRes', hit.k);
  EH_set('ehResLabel', hit.n);
  EH_toast('✅ 已选【' + hit.n + '】：首屏内联 ' + hit.hd + ' 张高清 / 视口懒加载串行间隔 ' +
           hit.gap + 'ms / 预取 ' + hit.margin + ' / 仅加载当前可见页');
  EH_toast((hit.hd === 0 ? 'ℹ 省流档只用 250px 缩略图、不请求 /s/ 页，最不易触发站方限频；' :
            'ℹ 高清档会在图片进入视口时按间隔逐张请求 /s/ 页，网络差建议降档；') +
           '★已打开的文章有正文缓存，请退出重进本文或清存档后生效');
  EH_toast('🌐 若要站方 /s/ 页直接返回该分辨率，再点「⚙ 同步站点分辨率(xr)」（会写入账号 uconfig，需你主动点）');
}
function EH_resStatus() {
