// ② 同步站点分辨率（POST /uconfig.php；全阶段 Toast + 回读确认）
function EH_uconfigSync() {
  var c = EH_resCfg(), d = EH_host();
  EH_toast('⚙ 开始同步站点分辨率：准备向 ' + d + '/uconfig.php 提交 xr=' + c.xr + ' ts=' + c.ts +
           '（会修改你的 E-Hentai 账号设置，仅本次主动点击执行）…');
  var body = 'xr=' + c.xr + '&ts=' + c.ts + '&apply=Apply';
  var opt = '{"method":"POST","body":' + JSON.stringify(body) +
            ',"headers":{"User-Agent":' + JSON.stringify(EH_UA) +
            ',"Cookie":' + JSON.stringify(EH_cookie(EH_gv('ehCookie', ''))) +
            ',"Content-Type":"application/x-www-form-urlencoded"' +
            ',"Referer":' + JSON.stringify(d + '/uconfig.php') + '}}';
  EH_toast('⚙ 正在提交设置（最多 20s）…');
  var r = '', b = '';
  try { r = java.connect(d + '/uconfig.php,' + opt, '', 20000); b = String(r.body()); }
  catch (e) { EH_toast('❌ 提交失败：' + String(e).slice(0, 90) + ' ⇒ 检查代理/Cookie，或改用面板档位（客户端侧已生效，不影响使用）'); return; }
  if (/Just a moment|cf-mitigated|challenge/i.test(b)) {
    EH_toast('❌ 被 Cloudflare 挑战挡下 ⇒ 请用「🌐 打开论坛登录」过盾后重试；面板档位不受影响'); return;
  }
  if (!/Settings were updated|Settings Updated/i.test(b)) {
    EH_toast('⚠ 未读到「Settings were updated」（' + b.length + 'B）⇒ 可能 Cookie 失效或账号无权限；面板档位仍已生效'); return;
  }
  EH_toast('✅ 站点设置已更新：xr=' + c.xr + '（' + (c.xr === '0' ? '自动1280x/移动780x' : c.xr === '1' ? '780x 省流' : '1280x 高清') +
           '）、ts=' + c.ts + '；正在回读确认…');
  // 回读确认（只读，一次）
  var chk = '';
  try {
    var h = { 'User-Agent': EH_UA, 'Cookie': EH_cookie(EH_gv('ehCookie', '')), 'Referer': d + '/uconfig.php' };
    chk = String(java.ajax(d + '/uconfig.php,{"headers":' + JSON.stringify(h) + '}'));
  } catch (e2) { chk = ''; }
  var m = chk.match(/<input[^>]*name=["']xr["'][^>]*checked[^>]*>/i);
  var got = m ? ((m[0].match(/value=["'](\d+)["']/i) || [])[1] || '?') : '?';
  EH_set('ehXR', got);
  EH_toast(got === c.xr ? '✅ 回读确认成功：站点当前 xr=' + got + '，已与面板档位一致。★退出重进文章即可看到新分辨率'
                        : '⚠ 回读 xr=' + got + '（期望 ' + c.xr + '）⇒ 账号可能禁用该档(4/5需Hath)，已记录；面板档位仍可用');
  EH_refresh();
}

// ---- 线路测速 / 切换（发布页式管理：测得的 ms 写进按钮文字；各阶段 Toast）----
// 站点无官方「网址发布页」，只有表站/里站两条固定线路 + 用户自填代理；
// 这里把原「站点切换」升级为「测速 → 点击切换」的线路面板，满足线路选择诉求。
function EH_pingOne(host) {
  var u = host + '/,{"headers":' + JSON.stringify({ 'User-Agent': EH_UA, 'Cookie': EH_cookie(EH_gv('ehCookie', '')) }) + '}';
  var t0 = new Date().getTime(), b = '';
  try { b = String(java.connect(u, '', 8000)); }
  catch (e) { return { ms: -1, len: 0, err: String(e).slice(0, 50) }; }
  var ms = new Date().getTime() - t0;
  if (/Exception|timeout|Failed to connect|SSLHandshake/i.test(b.slice(0, 200))) return { ms: ms, len: 0, err: '网络异常' };
  return { ms: ms, len: b.length, err: '' };
}
function EH_testDelay() {
  EH_toast('⚡ 开始测试两条线路延时（各 1 次请求，间隔 800ms，不会频繁访问）…');
  var hs = ['https://exhentai.org', 'https://e-hentai.org'], rec = [], i;
  for (i = 0; i < hs.length; i++) {
    EH_toast('⚡ 正在测 (' + (i + 1) + '/2) ' + hs[i] + ' …');
    var r = EH_pingOne(hs[i]);
    rec.push({ h: hs[i], ms: r.ms, len: r.len, err: r.err });
    EH_toast('⚡ ' + hs[i] + ' → ' + (r.ms >= 0 ? r.ms + 'ms' : '超时') +
             ' / ' + r.len + 'B' + (r.err ? '（' + r.err + '）' : ''));
    if (i === 0) { try { Packages.java.lang.Thread.sleep(800); } catch (eS) {} }
  }
  var ok = [];
  for (i = 0; i < rec.length; i++) if (rec[i].ms >= 0 && rec[i].len > 1000) ok.push(rec[i]);
  EH_set('ehPingEx', String((rec[0].ms >= 0 ? rec[0].ms : -1)));
  EH_set('ehPingTable', String((rec[1].ms >= 0 ? rec[1].ms : -1)));
  EH_set('ehPingText', '里站 ' + (rec[0].ms >= 0 ? rec[0].ms + 'ms' : '超时') +
                       ' / 表站 ' + (rec[1].ms >= 0 ? rec[1].ms + 'ms' : '超时'));
  EH_toast(ok.length ? '✅ 测速完成：' + EH_gv('ehPingText', '') + '。★延时已写入下方两个线路按钮，点按钮即切换（建议选 B 数大且延时小的）'
                     : '❌ 两条线路都没拿到完整页 ⇒ 检查 VPN / 代理，或点「🩺 一键自愈」；测速结果仍已记录');
  EH_refresh();
}
