    }
    // ② img 池：gdtl / gt100 / gt200 等大缩略图布局
    var imgPool = [], imRe = /<img[^>]*\s(?:data-src|src)=["']([^"']+)["']/gi, im;
    while ((im = imRe.exec(block)) !== null) {
