    // <a href="/s/HASH/ID-N"><div style="width:200px;height:283px;
    //   background:transparent url(SPRITE) -200px 0 no-repeat"></div></a>
    // 单行拼接：X 偏移按 200 递增，Y 恒 0，但每格宽度不同（200/162/168/174…）
    //
    // 整张 sprite 的真实宽度 = max(偏移 + 该格宽度)。同一 sprite 必须共用这个宽度，
    // 否则每格各算一个总宽 ⇒ 缩放不一致 ⇒ 越往下越偏。
    var grpEndW = {}, grpSeen = {}, i4;
    for (i4 = 0; i4 < bgPool.length; i4++) {
      var gu = bgPool[i4];
      var ax = Math.abs(bgX[i4] || 0);
      var cwI = (bgW.length > i4 && bgW[i4]) ? bgW[i4] : 200;
      var endX = ax + cwI;
      if (!grpEndW[gu] || endX > grpEndW[gu]) grpEndW[gu] = endX;
    }

    for (var n = 0; n < links.length; n++) {
      var t = '', sp = null;
      if (n < bgPool.length) {
        t = bgPool[n];
        var gw = (bgW.length > n && bgW[n]) ? bgW[n] : 200;
        var gh = (bgH.length > n && bgH[n]) ? bgH[n] : 283;
        var ox = Math.abs(bgX[n] || 0);
        var oy = Math.abs(bgY[n] || 0);
        var totW = grpEndW[t] || (ox + gw);
        if (totW < gw) totW = gw;
        sp = { w: gw, h: gh, ox: ox, oy: oy, tw: totW };
        grpSeen[t] = (grpSeen[t] || 0) + 1;
      } else if (n - bgPool.length < imgPool.length) {
        t = imgPool[n - bgPool.length];
      }
      list.push({ link: links[n], thumb: t, sprite: sp });
    }

    // ⑤ 兜底：链接一个都没抓到但存在图片池（站点改版时仍能显示图）
    if (!links.length && imgPool.length) {
      for (var q = 0; q < imgPool.length; q++) list.push({ link: pageUrl, thumb: imgPool[q] });
    }
