  var tagWatch  = gv('ehTagWatch',  '0') === '1';
  var watchMap = {};       // full tag name -> usertagId（watched 的）
  var tagWarn = '';
  // ★v6.8 mytags 同样缓存 30 分钟（ehTagCache = {t:..., tags:{name:id,...}}）
  var TAG_TTL = 30 * 60 * 1000;
  var tagCacheRaw = '';
  try { tagCacheRaw = String(source.get('ehTagCache') || ''); } catch (eTC) { tagCacheRaw = ''; }
  var tagCache = null;
  try { if (tagCacheRaw) tagCache = JSON.parse(tagCacheRaw); } catch (eTP) { tagCache = null; }
  var tagCacheFresh = (tagCache && tagCache.t && (new Date().getTime() - Number(tagCache.t)) < TAG_TTL && tagCache.tags);
  if (tagWatch && !tagCacheFresh) {
    try {
      var mb = String(java.ajax(origin + '/mytags' + OPT));
      if (mb.length > 3000 && mb.indexOf('usertag_') >= 0 &&
          !/Exception|temporarily banned|Sad Panda/i.test(mb.slice(0, 300))) {
        // <div id="usertag_N"> 段：tagpreview_N 的 title="ns:tag name" + tagwatch_N checked
        var ur = /<div id="usertag_(\d+)">([\s\S]*?)(?=<div id="usertag_|$)/g, um;
        while ((um = ur.exec(mb)) !== null) {
          var uid = um[1], useg = um[2];
          if (!/id="tagwatch_"|id="tagwatch_/.test(useg)) continue;
          var wm = new RegExp('id="tagwatch_' + uid + '"[^>]*checked').exec(useg);
          var pm = new RegExp('id="tagpreview_' + uid + '"[^>]*title="([^"]*)"').exec(useg);
          if (wm && pm) watchMap[stripTags(pm[1])] = uid;
        }
        // ★ 兜底：某些版本段被截断时，用全页正则按 id 逐条找
        if (!Object.keys(watchMap).length) {
          var wr2 = /id="tagwatch_(\d+)"[^>]*checked/g, w2;
          while ((w2 = wr2.exec(mb)) !== null) {
            var p2 = new RegExp('id="tagpreview_' + w2[1] + '"[^>]*title="([^"]*)"').exec(mb);
            if (p2) watchMap[stripTags(p2[1])] = w2[1];
          }
        }
        // ★v6.8 成功 → 写缓存
        try { source.put('ehTagCache', JSON.stringify({ t: new Date().getTime(), tags: watchMap })); } catch (eTW) { }
      } else {
        tagWarn = '· mytags 未取到（' + mb.length + 'B，订阅态可能不准）';
      }
    } catch (eT) { tagWarn = '· mytags 异常：' + String(eT).slice(0, 50); }
  } else if (tagWatch && tagCacheFresh) {
    // ★缓存命中：watchMap 从缓存还原（零请求）
    var tk = tagCache.tags;
    for (var tkn in tk) watchMap[tkn] = tk[tkn];
  }

  // ---- 3.7 tag 渲染（开关/watchMap/origin 此时全部就绪）----
  var tags = [];
  for (var tri = 0; tri < tagRows.length; tri++) {
    var row = tagRows[tri];
    tags.push('<div class="ehTagRow"><b>' + esc(row.ns) + '</b>：' +
      row.picks.map(function (p) {
        var su = origin + '/?f_search=' + encodeURIComponent(p.f);
        var label = tagSearch
          ? '<a class="ehTag" data-search="' + esc(su) + '" href="' + esc(su) + '">' + esc(p.t) + '</a>'
          : '<span class="ehTag">' + esc(p.t) + '</span>';
        var chip = '';
        if (tagWatch) {
          var w = watchMap[p.f];
          chip = '<button class="ehTagW' + (w ? ' on' : '') + '" data-full="' + esc(p.f) +
                 '" data-id="' + (w ? esc(String(w)) : '') + '">' +
                 (w ? '✓' : '＋') + '</button>';
        }
        return label + chip;
      }).join('') + '</div>');
  }

  var cols = gv('ehCols', '1');
  if (cols !== '2') cols = '1';
  var gridCols = (cols === '1') ? '1fr' : 'repeat(2,1fr)';

  var css = [
    'body{margin:0;padding:0;background:#1b1b1f;color:#e8e8ea;font:15px/1.7 system-ui,-apple-system,"Noto Sans CJK SC",sans-serif}',
    '.ehCard{background:#26262c;border:1px solid #3a3a44;border-radius:10px;padding:14px;margin-bottom:14px}',
    '.ehTitle{font-size:20px;font-weight:700;color:#fff;word-break:break-word;margin:0 0 4px}',
    '.ehJp{font-size:15px;color:#b9b9c6;margin:0 0 10px;word-break:break-word}',
    '.ehMeta{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:6px 14px;margin-top:10px}',
    '.ehMeta div{font-size:13px;color:#c9c9d4}.ehMeta b{color:#8ab4f8;font-weight:600}',
    '.ehTagRow{margin:5px 0;font-size:13px;color:#c9c9d4}.ehTagRow b{color:#f0a0a0}',
    '.ehTag{display:inline-block;background:#34343f;border:1px solid #454554;border-radius:5px;padding:1px 7px;margin:2px 4px 2px 0;font-size:12px;color:#dcdce6;text-decoration:none}',
    '.ehTag:active{background:#4a5a7a;border-color:#6a7fa8}',
    '.ehCover{max-width:100%;height:auto;display:block;margin:0 auto 12px;border-radius:8px}',
    '.ehGrid{display:block;line-height:0;font-size:0}',
    '.ehGrid a{display:block;margin:0;padding:0;background:transparent;border-radius:0;overflow:visible;text-decoration:none}',
    '.ehGrid a>img{width:100%;height:auto;display:block;margin:0;border:0;padding:0;background:transparent}',
    '.ehGrid a>div{display:block;margin:0;padding:0}',
    '.ehGrid> a >div{width:100%;display:block;margin:0;padding:0;background:transparent}',
    '.ehGrid span{display:none}',
    '.ehBar{font-size:13px;color:#a9a9b8;margin:10px 0}.ehBar a{color:#8ab4f8}',
    '.ehWarn{background:#4a2b2b;border:1px solid #8a4444;padding:10px;border-radius:8px;color:#ffd7d7;font-size:13px;margin-top:12px}',    '.ehFavRow{margin-top:12px;padding-top:10px;border-top:1px dashed #3a3a44}',
    '.ehFavHead{font-size:14px;font-weight:700;color:#f0a0a0;margin-bottom:6px}',
    '.ehFavErr{font-size:12px;color:#e8a0a0;background:#3a2626;border-radius:6px;padding:3px 8px;margin-left:6px}',
    '.ehFavStat{font-size:13px;color:#c9c9d4;margin:4px 0 8px}',
    '.ehFavB{display:inline-block;background:#34343f;border:1px solid #454554;border-radius:6px;color:#dcdce6;padding:5px 10px;margin:3px 6px 3px 0;font-size:13px;cursor:pointer;text-align:left}',
    '.ehFavB i{font-style:normal;color:#a9a9b8;font-size:11px;margin-left:5px}',
    '.ehFavB b{font-weight:600;color:#7ee787;margin-left:5px}',
    '.ehFavB.cur{background:#2d4a2d;border-color:#7ee787;color:#c8f0c8}',
    '.ehFavB.busy{opacity:0.5;pointer-events:none}',
    '.ehFavDel{background:#4a2b2b;border-color:#8a4444;color:#ffd7d7}',    '.ehTagW{display:inline-block;background:#2d4a2d;border:1px solid #4a7c4a;border-radius:4px;color:#c8f0c8;padding:0 6px;margin:0 8px 2px -2px;font-size:11px;cursor:pointer;vertical-align:middle}',
    '.ehTagW.on{background:#3a5f3a;border-color:#7ee787}',
    '.ehTagW.busy{opacity:0.5;pointer-events:none}',
    '.ehTagMode{font-size:12px;color:#a9a9b8;margin:6px 0 2px}',
    '.ehHud{position:fixed;right:8px;bottom:8px;z-index:60;background:transparent;color:#fff;font:12px/1.4 monospace;text-shadow:0 1px 3px rgba(0,0,0,.9),0 0 6px rgba(0,0,0,.8);pointer-events:none;padding:2px 4px}'
  ].join('');

  var h = '<!doctype html><html><head><meta charset="utf-8">' +
    '<meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1,minimum-scale=1,user-scalable=no">' +
    '<style>' + css + '</style></head><body>';
  var totalPages = filecount || thumbs.length;
  var hdCount0 = 0;
  for (var hk in hdMap) { hdCount0++; }
  // 正常不打扰：只显示页码。高清全失败时才提示一句。
  var hudHint = '';
  if (!hdCount0 && hdLinks.length) hudHint = ' ·无高清';
  h += '<div class="ehHud" id="ehHud" data-diag="' + esc(hdDiag) + '" data-hd="' + hdCount0 + '">' +
       '1 / ' + totalPages + hudHint + '</div>';
  h += '<div class="ehCard">';
  h += '<h1 class="ehTitle">' + esc(title || '（未取到标题）') + '</h1>';
  if (titleJp) h += '<div class="ehJp">' + esc(titleJp) + '</div>';

  h += '<div class="ehMeta">';
  function mi(k, v) { if (v) h += '<div><b>' + esc(k) + '：</b>' + esc(v) + '</div>'; }
  mi('分类', category); mi('上传者', uploader); mi('发布时间', posted);
  mi('页数', pagesTxt || (filecount ? filecount + ' pages' : '')); mi('大小', filesize);
  mi('评分', rating); mi('收藏', favCount);
  h += '</div>';
  if (tags.length) {
    if (tagSearch || tagWatch) {
      h += '<div class="ehTagMode">🏷 标签：' +
           (tagSearch ? '<b>点名字搜索</b>' : '名字不可点') + '　·　' +
           (tagWatch ? '<b>＋/✓ 订阅(再点取消)</b>' : '订阅未开') +
           (tagWarn ? ' <span class="ehFavErr">' + esc(tagWarn) + '</span>' : '') + '</div>';
    }
    h += '<div style="margin-top:6px">' + tags.join('') + '</div>';
  }

  var hdCount = 0;
  for (var hc in hdMap) { hdCount++; }

  h += '</div>';

  // ---- 4.5 收藏夹 UI（正文信息下方：状态行 + 10 个夹子 chip + 移出按钮）----
  if (showFav) {
    h += '<div class="ehFavRow">';
    h += '<div class="ehFavHead">📁 收藏夹' +
         (favErr ? ' <span class="ehFavErr">' + esc(favErr) + '</span>' : '') + '</div>';
    if (favCats) {
      var favHas = (favCur >= 0 || favCurName);
      h += '<div class="ehFavStat" id="ehFavStat">' + (favHas
        ? '⭐ 已收藏：' + esc(favCurName || ('夹 ' + favCur)) + '（再点该夹或 ➖ 移出）'
        : '☆ 未收藏 · 点击下方收藏夹加入') + '</div>';
      for (var fi2 = 0; fi2 < favCats.length; fi2++) {
        var fc = favCats[fi2];
        var isCur = (favCur === fc.n);
        h += '<button class="ehFavB' + (isCur ? ' cur' : '') + '" data-i="' + fc.n + '">' +
             esc(fc.name) + (fc.cnt ? '<i>' + esc(fc.cnt) + '</i>' : '') +
             (isCur ? '<b>✓</b>' : '') + '</button>';
      }
      if (favHas) h += '<button class="ehFavB ehFavDel" id="ehFavDel">➖ 移出收藏夹</button>';
    }
    h += '</div>';
  }

  // [书源] 简介不显示图片，图片全部在正文；此处删掉 ehGrid 渲染。
  if (more.length > 0 && bodies.length > 0 && bodies.length < more.length) {
    h += '<div class="ehWarn">⚠ 后续 ' + more.length + ' 个缩略图分页只成功取回 ' + bodies.length +
         ' 页（代理/限频/超时）。已显示能取到的全部；配好代理后重新打开本页即可补全。</div>';
  }
  if (tagWatch && tags.length) {
    // 页内 tag 订阅脚本：点 ＋/✓ → java.ajax POST /mytags（add / mass 删除）→ 即时改 DOM。
    // ★ add 与 delete 都返回 302 空响应（站方 POST→GET 重定向）⇒ 不用响应体判成功：
    //   java.ajax 拿到 302 跟随后的 /mytags 页面即为成功（失败则是异常堆栈串/空）。
    // ★ 动态值一律 JSON.stringify（261114 ReferenceError 铁律）；options 用对象 stringify。
    var tagLines = [
      '(function(){',
      'var O=__ORIGIN__,HDR=__HDR__;',
      'var Q=String.fromCharCode(34);',
      'function call(u){var w="";try{var r=java.ajax(u);if(typeof r==="string"){w=r;}else{try{w=String(r.body());}catch(e1){try{w=String(r);}catch(e2){w="";}}}}catch(e){w="";}return w;}',
      'function hip(){return "";}',
      'function H(){var h=null;try{h=JSON.parse(HDR);}catch(e0){h=null;}if(!h){h={Cookie:"",Referer:O+"/"};}h["Content-Type"]="application/x-www-form-urlencoded";return h;}',
      'function post(body){var _hp=hip();var _o={method:"POST",body:body,headers:H()};var opt=","+JSON.stringify(_o);var w=call(O+"/mytags"+opt);return (w&&w.indexOf("usertag_")>=0)?w:"";}',
      'function findId(w,full){var re=/id="tagpreview_([0-9]+)"[^>]*title="([^"]*)"/g,m;while((m=re.exec(w))!==null){if(m[2]===full)return m[1];}return "";}',
      'function onClick(ev){',
      '  if(ev&&ev.stopPropagation)ev.stopPropagation();',
      '  if(ev&&ev.preventDefault)ev.preventDefault();',
      '  var el=this;if(el.className.indexOf("busy")>=0)return;',
      '  var full=el.getAttribute("data-full")||"",id=el.getAttribute("data-id")||"";',
      '  if(!full)return;',
      '  var adding=!id;',
      '  el.className+=" busy";el.textContent="…";',
      '  var body=adding?("usertag_action=add&tagname_new="+encodeURIComponent(full)+"&tagwatch_new=on&tagcolor_new=&tagweight_new=10&usertag_target=0")',
      '                 :("usertag_action=mass&usertag_target=0&modify_usertags[]="+encodeURIComponent(id));',
      '  var resp=post(body),ok=!!resp;',
      '  el.className=el.className.split(" busy").join("");',
      '  if(ok&&adding){',
      '    var nid=findId(resp,full);',
      '    if(nid)el.setAttribute("data-id",nid);',
      '    try{source.put("ehTagCache","");}catch(eCT){}',
      '    el.className="ehTagW on";el.textContent="✓";',
      '    java.toast("✅ 已订阅标签："+full+(nid?"":"（退出重进可刷新订阅态）"));',
      '  }else if(ok){',
      '    el.removeAttribute("data-id");el.className="ehTagW";el.textContent="＋";',
      '    java.toast("✅ 已取消订阅："+full);',
      '  }else{',
      '    el.textContent=adding?"＋":"✓";',
      '    java.toast("❌ 订阅操作失败 ⇒ 检查登录态/网络");',
      '  }',
      '}',
      'var bs=document.querySelectorAll(".ehTagW");',
      'for(var k=0;k<bs.length;k++){bs[k].addEventListener("click",onClick);}',
      '})();'
    ].join(String.fromCharCode(10))
      .replace('__ORIGIN__', JSON.stringify(origin))
      .replace('__HDR__', JSON.stringify(PAGE_HDR));
    h += '<script>' + tagLines + '</script>';
  }

  if (showFav && favCats && favGid) {
    // 页内收藏夹脚本：点击夹子 → java.ajax POST gallerypopups.php → 成功后即时改 DOM。
    // ★ 零反斜杠纪律（261109 实锤）：不用正则字面量、不手拼引号 —— options 用
    //   JSON.parse(PAGE_HDR) 得对象 → 加 Content-Type → JSON.stringify 整个 options。
    // ★ java.ajax 失败不抛异常而是返回异常堆栈串（code 200）⇒ 判活查响应含 window.opener
    //   （261113 沙盒真机实锤的成功签名；失败串里不会出现该签名）。
    var fcLines = [
      '(function(){',
      'var G=__GID__,T=__TOK__,O=__ORIGIN__,HDR=__HDR__;',
      'var stat=document.getElementById("ehFavStat");',
      'function say(m){if(stat)stat.textContent=m;}',
      'var canAjaxNow=function(){return (typeof java!=="undefined"&&java!=null&&typeof java.ajax==="function");}',
      'function call(u){var w="";if(!canAjaxNow())return "NOBRIDGE";try{var r=java.ajax(u);if(typeof r==="string"){w=r;}else{try{w=String(r.body());}catch(e1){try{w=String(r);}catch(e2){w="";}}}}catch(e){w="";}return w;}',
      'function hip(){return "";}',
      'function ok(w){return w&&w.indexOf("window.opener")>=0;}',
      'var busy=false;',
      'function all(){return document.querySelectorAll(".ehFavB");}',
      'function cur(){var a=all();for(var i=0;i<a.length;i++)if(a[i].className.indexOf("cur")>=0)return a[i];return null;}',
      'function clr(el){if(!el)return;var ms=el.querySelectorAll("b");for(var i=0;i<ms.length;i++)el.removeChild(ms[i]);el.className="ehFavB";}',
      'function onClick(){',
      '  if(busy)return;',
      '  var el=this;',
      '  if(el.id==="ehFavDel"){act(el,false,"");return;}',
      '  var idx=el.getAttribute("data-i");',
      '  if(idx===null||idx==="")return;',
      '  act(el,!(cur()===el),idx);',
      '}',
      'function act(el,adding,idx){',
      '  busy=true;el.className+=" busy";',
      'if(!canAjaxNow()){say("❌ 此环境无 java 桥（E 版 WebView 限制），无法收藏");return;}',
      '  say(adding?"⏳ 正在加入收藏夹…":"⏳ 正在移出收藏夹…");',
      'try{',
      '  var body=adding?("favcat="+idx+"&favnote=&apply=Add+to+Favorites&update=1")',
      '                 :"favcat=favdel&favnote=&apply=Apply+Changes&update=1";',
      '  var H=null;try{H=JSON.parse(HDR);}catch(e0){H=null;}',
      '  if(!H){H={Cookie:"",Referer:O+"/"};}',
      '  H["Content-Type"]="application/x-www-form-urlencoded";',
      '  var _hp=hip();var _o={method:"POST",body:body,headers:H};',
      '  var opt=","+JSON.stringify(_o);',
      '  var u=O+"/gallerypopups.php?gid="+G+"&t="+T+"&act=addfav",w="";',
      '  w=call(u+opt);',
      '  el.className=el.className.split(" busy").join("");',
      '  if(ok(w)){',
      '    var s2=cur();if(s2&&s2!==el)clr(s2);',
      '    clr(el);',
      '    try{source.put("ehFavCache","");}catch(eCF){}',
      '    if(adding){el.className="ehFavB cur";var b=document.createElement("b");b.textContent="✓已入";el.appendChild(b);say("✅ 已加入收藏夹（站内即时生效）");}',
      '    else{say("✅ 已移出收藏夹");}',
      '  }else{',
      '    say("❌ 操作失败（"+(w?w.length+"B 异常响应":"空响应")+"）⇒ 检查尝试登录态/网络后重试");',
      '  }',
      '  }catch(eA){say("❌ 异常："+String(eA).slice(0,80));}',
      '  finally{busy=false;}',
      '}',
      'var bs=all();',
      'for(var k=0;k<bs.length;k++){bs[k].addEventListener("click",onClick);}',
      '})();',
    ].join(String.fromCharCode(10))
      .replace('__GID__', JSON.stringify(favGid))
      .replace('__TOK__', JSON.stringify(favTok))
      .replace('__ORIGIN__', JSON.stringify(origin))
      .replace('__HDR__', JSON.stringify(PAGE_HDR));
    h += '<script>' + fcLines + '</script>';
  }
  // [书源] 简介无图片，删掉 ehGrid 懒加载脚本。
  h += '</body></html>';
  return h;
})();return '<useweb>' + String(_html==null?'':_html) + '</useweb>';})()

