  var b = String(baseUrl||'').split('#')[0];
  var out = [], seen = {};
  function add(u, name){
    if (!u || seen[u]) return;
    seen[u]=1;
    out.push(String(JSON.stringify({name:name, url:u})));
  }
  // 首页 ?p=0：从当前详情页 HTML(result) 的 ptb 抓最大页码
  var s = '';
  try { s = (result&&result.html)?String(result.html()):String(result); } catch(e){ s=String(result); }
  var maxP = 0;
  var ptb = /<table[^>]*class=["'][^"']*\bptb\b[^"']*["'][^>]*>([\s\S]*?)<\/table>/i.exec(s);
  if (ptb) { var re=/[?&]p=(\d+)/g,m; while((m=re.exec(ptb[1]))!==null){var n=Number(m[1]);if(n>maxP)maxP=n;} }
  // 无 ptb：单页画廊，只有首页
  add(b, '📖 第 01-20 页');
  for (var p=1; p<=maxP; p++) {
    var lo=p*20+1, hi=(p+1)*20;
    add(b+(b.indexOf('?')>=0?'&':'?')+'p='+p, '📖 第 '+lo+'-'+hi+' 页');
  }
  return out;
})()

