/* 音频播放（261119 终极正解·数据完整性修复）：m3u8 分片是 AES-128 加密伪装 .jpg(实为TS)。
   ①★★ java.ajax/ajaxAll 把密文按字符串解码，非法字节变 U+FFFD 永久丢失（60片全中招）→
      必须 okhttp3 原生 body.bytes() 拿无损 byte[]；②★★ 密文是 AES/CBC/PKCS5Padding
      （分片尾部04/08 padding实锤），用 NoPadding 保留 padding 会让 TS 包错位→3003，
      必须 PKCS5Padding 自动去 padding；③拼接成 mod188=0、188边界同步100%的真TS；
      ④返回 JSON 数组 ["file://...ts"] 让 E 版走 DefaultDataSource（绕开1004）。
   首次 okhttp 串行下载约34秒+缓存，二次命中秒开。 */
function YS_rawBytes(url){
  var C=Packages.okhttp3.OkHttpClient,R=Packages.okhttp3.Request;
  var client=new C();
  return client.newCall(new R.Builder().url(String(url)).build()).execute().body().bytes();
}
function YS_hex(b){var h=new Packages.java.math.BigInteger(1,b).toString(16);if(h.length%2)h='0'+h;return h==='0'?'':h;}
function YS_cacheDir(J){
  var pkg='',d='';
  try{var tmp=String(Packages.java.lang.System.getProperty('java.io.tmpdir')||'');var ps=tmp.split(String.fromCharCode(47));pkg=ps[ps.length-2]}catch(e){}
  if(pkg&&pkg.indexOf('.')>0)d='/storage/emulated/0/Android/data/'+pkg+'/cache';
  if(!d){try{J.readFile('/')}catch(e0){var s=String(e0),q=s.indexOf(String.fromCharCode(47)+'storage'+String.fromCharCode(47)+'emulated');if(q>=0){var z=s.indexOf(String.fromCharCode(47)+'cache',q);if(z>q)d=s.substring(q,z+6)}}}
  if(!d)d='/storage/emulated/0/Android/data/com.legado.app.release/cache';
  return d;
}
function YS_audioLocal(J,r,title){
  var h=YS_player(J,r);
  if(!h||!h.url)return '';
  var url=String(h.url).split(YS_BS).join('/');
  try{
    var m3=String(J.ajax(url));
    var md5=String(J.digestHex(m3,'MD5'));
    var ck='ysok_'+md5,cached='';
    try{cached=String(source.get(ck)||'')}catch(e){}
    if(cached&&cached.indexOf('file://')>=0)return cached;
    var dir=url.substring(0,url.lastIndexOf('/')+1);
    var origin=url.substring(0,url.indexOf('/',url.indexOf('//')+2));
    var lines=m3.split(YS_NL),segs=[];
    for(var i=0;i<lines.length;i++){var L=String(lines[i]).trim();if(L&&L.charAt(0)!=='#')segs.push(L.indexOf('http')===0?L:dir+L);}
    if(!segs.length)return url;
    var key=YS_rawBytes(origin+'/vod.key');
    var iv=J.hexDecodeToByteArray('00000000000000000000000000000000');
    var C=Packages.javax.crypto.Cipher,K=Packages.javax.crypto.spec.SecretKeySpec,V=Packages.javax.crypto.spec.IvParameterSpec;
    var BAOS=Packages.java.io.ByteArrayOutputStream,bos=new BAOS(),ok=0;
    for(var k=0;k<segs.length;k++){
      try{
        var cipher=YS_rawBytes(segs[k]);
        var ci=C.getInstance('AES/CBC/PKCS5Padding');
        ci.init(C.DECRYPT_MODE,new K(key,'AES'),new V(iv));
        var plain=ci.doFinal(cipher);
        bos.write(plain,0,plain.length);ok++;
      }catch(e3){}
    }
    if(ok<segs.length)return url;
    var all=bos.toByteArray();
    if(!all.length||(all[0]&255)!==71||all.length%188!==0)return url;  // 0x47 + TS对齐
    var hx=YS_hex(all);
    var name='ysa_'+md5+'.ts';
    var path=String(J.downloadFile(hx,name+',{"type":"ts"}'));
    if(!path)return url;
    var fp='file://'+YS_cacheDir(J)+path;
    // ★两版关键：JSON 数组 → isJsonArray()=true → getMediaSource(DefaultDataSource 支持 file://)
    var ret=JSON.stringify([fp]);
    try{source.put(ck,ret)}catch(e4){}
    return ret;
  }catch(e5){}
  return url;
}
function YS_novel(J,r){
  var d=YS_doc(J,r),ps=d.select('div.module-novel-detail div.content p'),o=[];
  for(var i=0;i<ps.size();i++){var t=String(ps.get(i).text()).trim();if(t)o.push('　　'+t);}
  return o.join(YS_NL);
}

