  var hosts=YS_get('ys_hosts','').split(',');if(!hosts.length||!hosts[0])hosts=YS_DOMAINS.slice(0);
  var urls=[];for(var i=0;i<hosts.length;i++)urls.push('https://'+hosts[i]+':'+YS_PORTS[0]+'/');
  var res=[];try{res=java.ajaxAll(urls)}catch(e){}
