var resp=java.ajax(baseUrl);
var d=JSON.parse(resp).list[0];
var lines=String(d.vod_play_url||'').split('$$$');
var line=lines[0];
for(var i=0;i<lines.length;i++){if(lines[i].indexOf('m3u8')>-1){line=lines[i];break;}}
var arr=line.split('#').filter(function(x){return x.trim().length>0;});
var list=arr.map(function(u,i){
  var idx=u.indexOf('$');
  if(idx>0){return {name:u.substring(0,idx)||('第'+(i+1)+'集'),url:u.substring(idx+1)};}
  return {name:'第'+(i+1)+'集',url:u.trim()};
});
list;

