// ============ Jable 视频书源 · 登录/线路管理面板 ============
// loginUi <js> 与 action 共用本文件（SourceLoginDialog 拼 "$loginJS\n$buttonFunctionJS"）。
// ★用到 java 的函数必须放这里（jsLib 共享 scope 看不到 evalJS 注入的 java）。
// 发布页输入框名: pub；线路: jbLine / jbLines（jsLib JB_* 经 this.source 存取同一真身）
function JB_toast(s, long) {
  try { if (long) java.longToast(s); else java.toast(s); } catch (e) { try { java.toast('' + s); } catch (e2) {} }
}
function JB_reUi() {
  try { java.reLoginView(); } catch (e) { try { java.reLoginView(false); } catch (e2) { try { java.reUiView(false); } catch (e3) {} } }
}
function JB_hdrPanel() {
  return "{\"User-Agent\": \"Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36\", \"Accept-Language\": \"zh-CN,zh;q=0.9\"}";
}

// ---- 发布页 → Jable 线路池（java 函数必须在此；x99dh.github.io 静态导航 base64）----
function JB_fetchPub() {
  var navs = ['https://x99dh.github.io/', 'https://x99dh.pages.dev/'];
  for (var n = 0; n < navs.length; n++) {
    try {
      var r = java.connect(navs[n], JB_hdrPanel(), 15000);
      var b = r.body() + '';
      var m = b.match(/encodedData\s*=\s*'([^']+)'/);
      if (!m) continue;
      var j = decodeURIComponent(java.base64Decode(m[1]));
      var arr = JSON.parse(j);
      for (var i = 0; i < arr.length; i++) {
        if (String(arr[i].name) === 'Jable' && arr[i].urls) {
          var out = [];
          for (var k = 0; k < arr[i].urls.length; k++) {
            var u = String(arr[i].urls[k].url || '').replace(/\/enter\/?$/, '').replace(/\/+$/, '');
            if (u.indexOf('http') === 0 && out.indexOf(u) < 0) out.push(u);
          }
          if (out.length) return {lines: out, def: String(arr[i].url || out[0]).replace(/\/enter\/?$/, '').replace(/\/+$/, ''), from: navs[n]};
        }
      }
    } catch (e) {}
  }
  return null;
}

// 并发测速（status.html 返回 2 字节 'ok' + callTime 判活），ms 写按钮，最快自动切换
function JB_pickFastest() {
  var list = JB_lineList.call(this);
  if (!list.length) return null;
  var best = -1, bestMs = 999999, tested = 0, lastErr = '', mode = '';
  var i, ms, txt, rs = null;
  try {
    var more = [];
    for (i = 0; i < list.length; i++) {
      more.push(list[i] + '/status.html?t=' + Date.now() + ',{"headers":' + JB_hdrPanel() + ',"retry":0}');
    }
    rs = java.ajaxAll(more, true);
    var n = (rs && (rs.length || (rs.size ? rs.size() : 0))) || 0;
    var rsOk = false;
    try {
      var ct0 = parseInt(rs[0].callTime(), 10);
      var bd0 = String(rs[0].body() || '');
      rsOk = (n >= list.length && ct0 > 0 && bd0.indexOf('Exception') < 0 && bd0.indexOf('timeout') < 0);
    } catch (eChk) { rsOk = false; }
    if (rsOk) {
      mode = 'ajaxAll';
      for (i = 0; i < n; i++) {
        ms = 999999; txt = '';
        try { ms = parseInt(rs[i].callTime(), 10); } catch (e) {}
        try { txt = String(rs[i].body() || ''); } catch (e2) {}
        if (txt.trim() !== 'ok' || ms > 15000 || ms < 0) ms = 999999;
        try { this.source.put('jbSp' + i, ms === 999999 ? '超时' : ms + 'ms'); } catch (e9) {}
        if (ms < 15000) tested++;
        if (ms < bestMs) { bestMs = ms; best = i; }
      }
    } else { rs = null; }
  } catch (e) { lastErr = 'ajaxAll:' + String(e).substring(0, 40); rs = null; }
  if (!rs) {
    mode = 'connect';
    for (i = 0; i < list.length; i++) {
      ms = 999999; txt = '';
      try {
        var r = java.connect(list[i] + '/status.html?t=' + Date.now(), JB_hdrPanel(), 6000);
        var ct = 0; try { ct = parseInt(r.callTime(), 10); } catch (e3) {}
        try { txt = String(r.body() || ''); } catch (e4) {}
        if (txt.trim() === 'ok' && ct >= 0) ms = ct;
      } catch (e5) { lastErr = 'connect:' + String(e5).substring(0, 40); }
      try { this.source.put('jbSp' + i, ms === 999999 ? '超时' : ms + 'ms'); } catch (e6) {}
      if (ms < 15000) tested++;
      if (ms < bestMs) { bestMs = ms; best = i; }
    }
  }
  try { this.source.put('jbDiag', 'mode=' + mode + ' tested=' + tested + ' best=' + best + ' err=' + lastErr); } catch (e7) {}
  if (best >= 0 && bestMs < 15000) {
    JB_writeLine.call(this, String(list[best]));
    return {best: best, line: String(list[best]), ms: bestMs, tested: tested};
  }
  return null;
}

// 🧭 一键从发布页获取网址路线（取回 Jable 18 条线路 + 自动测速选最快）
function JB_actionFetch() {
  JB_toast('🧭 正在解析 x99dh 发布页 Jable 线路…', true);
  try {
    var res = JB_fetchPub();
    if (!res || !res.lines || !res.lines.length) {
      JB_toast('❌ 未解析到线路，检查网络或稍后再试', true);
      return;
    }
    JB_storeLines.call(this, res.lines);
    var d = JB_getData.call(this);
    d.jbPage = '0';
    JB_saveData.call(this, d);
    JB_writeLine.call(this, String(res.def || res.lines[0]));
    JB_toast('✅ 获取 ' + res.lines.length + ' 条线路，正在测速选最快…', true);
    var fast = JB_pickFastest.call(this);
    if (fast) {
      JB_toast('⚡ 已选最快：' + fast.line.replace(/^https?:\/\//, '') + ' ' + fast.ms + 'ms（' + fast.tested + '条）', true);
    } else {
      JB_toast('✅ 线路已获取（自动测速失败，可点⏱手动测）', true);
    }
    JB_reUi();
  } catch (e) { JB_toast('❌ 解析失败：' + String(e).substring(0, 60), true); }
}

// ⏱ 测速按钮：ms 写各线路按钮（viewName 动态显示），最快自动切换
function JB_actionTest() {
  var list = JB_lineList.call(this);
  if (!list.length) { JB_toast('⚠️ 请先点🧭获取线路', true); return; }
  JB_toast('⏱ 正在测速 ' + list.length + ' 条线路…', true);
  var fast = JB_pickFastest.call(this);
  if (fast) {
    JB_toast('⚡ 最快：' + fast.line.replace(/^https?:\/\//, '') + ' ' + fast.ms + 'ms（' + fast.tested + '条，已切换）', true);
  } else {
    JB_toast('⚠️ 全部线路测速失败，请检查网络', true);
  }
  JB_reUi();
}

// 线路按钮动态文本：▶当前 + ⚡ms + 域名
function JB_lineBtn(i) {
  try {
    var list = JB_lineList.call(this);
    var page = parseInt(JB_getData.call(this).jbPage || '0', 10);
    var idx = page * 12 + i;
    if (idx >= list.length) return '　（空）';
    var u = String(list[idx]).replace(/^https?:\/\//, '').replace(/\/+$/, '');
