o.kind=(h.match(/name="keywords" content="([^"]*)"/)||['',''])[1];
var h6=(h.match(/<div class="info-header"[\s\S]*?<h6>([\s\S]*?)<\/h6>/)||['',''])[1]||'';
var nums=[];h6.replace(/<span class="mr-3">([^<]*)<\/span>/g,function(a,c){nums.push(c.trim());});
o.desc=(o.desc||'')+(nums.length?' · '+nums.join(' · '):'');
return JSON.stringify(o)})()

